
import { useState } from 'react';
import PostCard from '../components/PostCard';
import { posts, getAllCategories } from '../data/posts';
import { Post } from '../data/types';

const Home = () => {
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const categories = getAllCategories();

  const filteredPosts: Post[] = selectedCategory 
    ? posts.filter(post => post.category === selectedCategory)
    : posts;

  return (
    <div className="max-w-6xl mx-auto px-4 py-8">
      {/* Hero Section */}
      <section className="mb-12 text-center py-16 bg-gradient-to-r from-blue-900 to-blue-700 rounded-2xl text-white">
        <h1 className="text-4xl md:text-5xl font-bold mb-4">欢迎来到我的博客</h1>
        <p className="text-xl text-blue-100 max-w-2xl mx-auto">
          分享技术见解，记录生活感悟，与你一起成长
        </p>
      </section>

      {/* Category Filter */}
      <section className="mb-8">
        <div className="flex flex-wrap gap-3 justify-center">
          <button
            onClick={() => setSelectedCategory(null)}
            className={`px-4 py-2 rounded-full font-medium transition-all duration-200 ${
              !selectedCategory 
                ? 'bg-blue-800 text-white' 
                : 'bg-white text-gray-700 hover:bg-gray-100'
            }`}
          >
            全部
          </button>
          {categories.map((category) => (
            <button
              key={category}
              onClick={() => setSelectedCategory(category)}
              className={`px-4 py-2 rounded-full font-medium transition-all duration-200 ${
                selectedCategory === category 
                  ? 'bg-blue-800 text-white' 
                  : 'bg-white text-gray-700 hover:bg-gray-100'
              }`}
            >
              {category}
            </button>
          ))}
        </div>
      </section>

      {/* Posts Grid */}
      <section>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {filteredPosts.map((post) => (
            <PostCard key={post.id} post={post} />
          ))}
        </div>
        {filteredPosts.length === 0 && (
          <div className="text-center py-16 text-gray-500">
            暂无文章
          </div>
        )}
      </section>
    </div>
  );
};

export default Home;
