
import { useParams, Link } from 'react-router-dom';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { getPostById, posts } from '../data/posts';

const PostDetail = () => {
  const { id } = useParams<{ id: string }>();
  const post = id ? getPostById(id) : undefined;

  if (!post) {
    return (
      <div className="max-w-4xl mx-auto px-4 py-16 text-center">
        <h1 className="text-2xl font-bold text-gray-900 mb-4">文章未找到</h1>
        <Link to="/" className="text-blue-600 hover:underline">
          返回首页
        </Link>
      </div>
    );
  }

  const relatedPosts = posts
    .filter(p => p.id !== post.id && p.category === post.category)
    .slice(0, 2);

  return (
    <article className="max-w-4xl mx-auto px-4 py-8">
      {/* Back Button */}
      <Link 
        to="/" 
        className="inline-flex items-center text-gray-600 hover:text-blue-800 mb-6 transition-colors"
      >
        <svg className="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
        </svg>
        返回首页
      </Link>

      {/* Cover Image */}
      <div className="mb-8 rounded-xl overflow-hidden shadow-lg">
        <img 
          src={post.coverImage} 
          alt={post.title} 
          className="w-full h-64 md:h-96 object-cover"
        />
      </div>

      {/* Post Header */}
      <header className="mb-8">
        <div className="flex items-center gap-3 mb-4">
          <span className="bg-blue-100 text-blue-800 text-sm font-medium px-3 py-1 rounded">
            {post.category}
          </span>
          <span className="text-gray-500">{post.date}</span>
          <span className="text-gray-500">· {post.readTime}</span>
        </div>
        <h1 className="text-3xl md:text-4xl font-bold text-gray-900 mb-4">
          {post.title}
        </h1>
        <div className="flex flex-wrap gap-2">
          {post.tags.map((tag, index) => (
            <span 
              key={index} 
              className="text-gray-600 text-sm bg-gray-100 px-3 py-1 rounded-full"
            >
              #{tag}
            </span>
          ))}
        </div>
      </header>

      {/* Post Content */}
      <div className="prose prose-lg max-w-none mb-12">
        <ReactMarkdown 
          remarkPlugins={[remarkGfm]}
          components={{
            h1: ({ ...props }) => <h1 className="text-2xl font-bold text-gray-900 mt-8 mb-4" {...props} />,
            h2: ({ ...props }) => <h2 className="text-xl font-semibold text-gray-900 mt-6 mb-3" {...props} />,
            h3: ({ ...props }) => <h3 className="text-lg font-semibold text-gray-900 mt-5 mb-2" {...props} />,
            p: ({ ...props }) => <p className="text-gray-700 leading-relaxed mb-4" {...props} />,
            ul: ({ ...props }) => <ul className="list-disc list-inside text-gray-700 mb-4 space-y-1" {...props} />,
            ol: ({ ...props }) => <ol className="list-decimal list-inside text-gray-700 mb-4 space-y-1" {...props} />,
            code: ({ className, children, ...props }) => {
              const match = /language-(\w+)/.exec(className || '');
              return match ? (
                <pre className="bg-gray-900 text-gray-100 p-4 rounded-lg overflow-x-auto mb-4">
                  <code className={className} {...props}>{children}</code>
                </pre>
              ) : (
                <code className="bg-gray-100 text-red-600 px-1.5 py-0.5 rounded text-sm" {...props}>{children}</code>
              );
            },
            blockquote: ({ ...props }) => (
              <blockquote className="border-l-4 border-blue-500 pl-4 py-1 my-4 bg-blue-50 text-gray-700" {...props} />
            ),
            a: ({ ...props }) => (
              <a className="text-blue-600 hover:underline" target="_blank" rel="noopener noreferrer" {...props} />
            ),
          }}
        >
          {post.content}
        </ReactMarkdown>
      </div>

      {/* Related Posts */}
      {relatedPosts.length > 0 && (
        <section className="border-t border-gray-200 pt-8">
          <h2 className="text-2xl font-bold text-gray-900 mb-6">相关文章</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {relatedPosts.map((relatedPost) => (
              <Link 
                key={relatedPost.id} 
                to={`/post/${relatedPost.id}`}
                className="group bg-white rounded-lg shadow-md overflow-hidden hover:shadow-lg transition-shadow"
              >
                <div className="h-40 overflow-hidden">
                  <img 
                    src={relatedPost.coverImage} 
                    alt={relatedPost.title} 
                    className="w-full h-full object-cover transition-transform duration-300 group-hover:scale-105"
                  />
                </div>
                <div className="p-4">
                  <h3 className="font-semibold text-gray-900 group-hover:text-blue-800 transition-colors">
                    {relatedPost.title}
                  </h3>
                  <p className="text-sm text-gray-500 mt-1">{relatedPost.date}</p>
                </div>
              </Link>
            ))}
          </div>
        </section>
      )}
    </article>
  );
};

export default PostDetail;
